CREATE FUNCTION dbo.lastavrage (@CODE AS nvarchar(15),@ANBAR AS int,@DT as bigint)    RETURNS FLOAT    AS   BEGIN    DECLARE @AVG FLOAT SELECT  TOP 1 @AVG = AVRAGE  FROM  dbo.lastavrage_sub(@DT, @CODE, @ANBAR) lastavrage_sub ORDER BY DATE_N DESC, NUMBER DESC   IF @AVG is  NULL SELECT     @AVG = FI_A FROM dbo.STUF_FSK WHERE (CODE =  @CODE) AND (ANBAR = @ANBAR)  IF  @AVG is  NULL   set @AVG = 0    RETURN @AVG   End
